diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 77b0c66..847afea 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1853,6 +1853,109 @@ void process_dump(des_proc* p, log_sev sev)


 // ( SOLUZIONE 2025-06-05
+extern "C" bool c_swap_out(natl pid, char *buf)
+{
+	des_proc* p;
+
+	if (pid > MAX_PROC_ID) {
+		flog(LOG_WARN, "swap_out: pid non valido");
+		c_abort_p();
+		return false;
+	}
+
+	if (proc_table[pid] == nullptr)
+		return false;
+
+	p = proc_table[pid];
+
+	if (p->livello == LIV_SISTEMA || p == esecuzione) {
+		flog(LOG_WARN, "swap_out: errore di protezione");
+		c_abort_p();
+		return false;
+	}
+
+	if (p->swapped_out)
+		return false;
+
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, true)) {
+		flog(LOG_WARN, "swap_out: buffer non valido");
+		c_abort_p();
+		return false;
+	}
+
+	for (natq i = 0; i < DIM_USR_STACK; i += sizeof(natq)) {
+		paddr pa = trasforma(p->cr3, fin_utn_p - DIM_USR_STACK + i);
+		if (!pa) {
+			flog(LOG_WARN, "swap_out: pila utente non mappata");
+			c_abort_p();
+			return false;
+		}
+		natq val;
+		memcpy(&val, voidptr_cast(pa), sizeof(natq));
+		*(natq*)(buf + i) = val;
+	}
+
+	distruggi_pila(p->cr3, fin_utn_p, DIM_USR_STACK);
+	p->swapped_out = true;
+
+	return true;
+}
+
+extern "C" bool c_swap_in(natl pid, const char *buf)
+{
+	des_proc* p;
+
+	if (pid > MAX_PROC_ID) {
+		flog(LOG_WARN, "swap_in: pid non valido");
+		c_abort_p();
+		return false;
+	}
+
+	if (proc_table[pid] == nullptr)
+		return false;
+
+	p = proc_table[pid];
+
+	if (p->livello == LIV_SISTEMA) {
+		flog(LOG_WARN, "swap_in: errore di protezione");
+		c_abort_p();
+		return false;
+	}
+
+	if (!p->swapped_out)
+		return false;
+
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, false)) {
+		flog(LOG_WARN, "swap_in: buffer non valido");
+		c_abort_p();
+		return false;
+	}
+
+	if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE)) {
+		flog(LOG_WARN, "swap_in: creazione pila utente fallita");
+		return false;
+	}
+
+	for (natq i = 0; i < DIM_USR_STACK; i += sizeof(natq)) {
+		paddr pa = trasforma(p->cr3, fin_utn_p - DIM_USR_STACK + i);
+		if (!pa) {
+			flog(LOG_WARN, "swap_in: pila utente non mappata");
+			c_abort_p();
+			return false;
+		}
+		natq val = *(natq*)(buf + i);
+		memcpy(voidptr_cast(pa), &val, sizeof(natq));
+	}
+
+	p->swapped_out = false;
+
+	if (p->scheduled) {
+		p->scheduled = false;
+		inserimento_lista(pronti, p);
+	}
+
+	return true;
+}
 //   SOLUZIONE 2025-06-05 )


